            "swapping_pxa_to_pxs_is_instant_the": "PXA naar PXS converteren gaat direct: de helft van de PXA wordt meteen geconverteerd, min 5% kosten, terwijl de andere helft als onderpand vergrendeld blijft en na ~3,5 dag terugkomt, aangepast aan de prijs van dat moment. PXS naar PXA converteren is kosteloos en wordt na ~3,5 dag afgewikkeld, tegen de mediaanprijs van de witnesses op dat moment.",
