            "strong_strong_can_transfer_pixa_power_directly": "<strong>@{{username}}</strong> kan Pixa Power rechtstreeks naar een ander account overboeken en zo de standaard power-down-cyclus van 13 weken omzeilen. Deze treasury is een multi-signature-account, dus geen enkele afzonderlijke login kan de middelen verplaatsen — gebruik <strong>Bulkoverboeking</strong> hieronder, waar elke sleutelhouder dezelfde batch afzonderlijk ondertekent voordat die wordt samengevoegd en uitgezonden.",
