            "beware_of_spam_and_phishing_links_in": "Pas op voor spam- en phishinglinks in overboekingsmemo’s. Open geen links van gebruikers die je niet vertrouwt. Geef je privésleutels nooit aan websites van derden. Transacties verschijnen pas zodra ze op de blockchain zijn bevestigd; dat kan enkele minuten duren.",
