            "are_you_sure_you_want_to_swap": "Weet je zeker dat je {{amount}} PXA naar PXS wilt converteren? De helft wordt meteen geconverteerd, min 5% kosten, en de PXS wordt direct bijgeschreven. De andere helft blijft als onderpand vergrendeld en komt na ~3,5 dag terug, aangepast aan de PXA-prijs van dat moment; is die prijs gehalveerd, dan komt er niets terug. Conversies kunnen niet worden teruggedraaid.",
