            "full_transfer_ledger_for_the_period_received": "Volledig overboekingsgrootboek voor de periode. Ontvangen overboekingen zijn verwervingen (ze bepalen de kostprijs); alleen verzendingen naar derden en swaps zijn belastbare vervreemdingen, hieronder vermeld onder Vervreemdingen.",
