            "not_taxable_disposals_or_income_proposal_fees": "Geen belastbare vervreemdingen of inkomsten. Voorstelkosten verlaten het account en verlagen je bezit; afgeronde spaaropnames en power-ups zijn interne verplaatsingen, getoond voor de volledigheid.",
            "seen_in_history_but_not_booked_into": "Wel in de geschiedenis gezien, maar niet in bovenstaande cijfers geboekt ({{skippedTotal}} operaties) — sociale/governance-acties zonder saldo-effect, inkomsten die al bij het claimen zijn geteld, of bewegingen die pas bij een latere uitvoering worden afgewikkeld:",
            "reconstructed_from_classified_events": "Gereconstrueerd uit {{ingest}} geclassificeerde gebeurtenissen.{{text}}{{fiat}}{{text_2}}{{note}}",
            "deductions_optional_losses_you_carried_forward_f": "Aftrekposten — optioneel. Verliezen die je uit eerdere jaren hebt overgedragen, worden verrekend met de winsten van dit jaar; het bedrag bij de jaarlijkse vrijstelling is hoeveel van de vrijstelling van je land je elders al hebt gebruikt. Automatisch toegepast waar je jurisdictie erin voorziet.",
            "send_labels_are_assigned_in_the_classify": "Verzendlabels worden toegekend in de stap Classificeren en per account onthouden. Bewerk ze desgewenst in bulk in een spreadsheet:",
            "say_what_each_outbound_send_was_so": "Geef aan wat elke uitgaande verzending was, zodat deze correct wordt belast. Elke verzending wordt als een belastbare verkoop behandeld tenzij je er een label aan geeft — markeren als je eigen exchange, je eigen wallets, gift of donatie verandert de belasting. Labels worden de volgende keer onthouden. Doorgaan past ze toe en herberekent het rapport.",
            "nothing_to_classify_no_outbound_transfers_to": "Niets te classificeren — er zijn geen uitgaande overboekingen naar derden in je geschiedenis gevonden. Ga door om te controleren en te exporteren.",
            "opening_balances_are_tokens_you_already_held": "Beginsaldi zijn tokens die je al bezat vóór de eerste geregistreerde operatie van dit account. Stel ze in zodat oudere vervreemdingen een echte kostprijs hebben in plaats van een (overdreven) winst tegen nul kosten. Kosten zijn het totaal dat je voor dat beginsaldo hebt betaald, in {{cur}}.",
            "generate_a_record_of_your_on_chain": "Genereer een overzicht van je on-chain activiteit over een datumbereik, voor de belasting geclassificeerd door de FairFlow-engine. Vul de opties in, classificeer je verzendingen en exporteer vervolgens als PDF, CSV of JSON.",
            "values_use_the_wallets_current_price_a": "Waarden gebruiken de huidige {{fiat}}-prijs van de wallet — één live momentopname zonder historische feed, dus het bezitstotaal is nauwkeurig maar gerealiseerde winsten zijn benaderingen (de opbrengst en de kostprijs van een vervreemding delen dezelfde huidige prijs). Sluit een historische oracle-/Kursliste-bron aan voor exacte winsten.",
            "fiat_values_come_from_the_engines_pxs": "Fiatwaarden komen van de demo-prijsprovider van de engine met PXS-referentie ({{priceDataVersion}}) — sluit een echte oracle-/Kursliste-bron aan voordat je op de cijfers vertrouwt.",
