            "delivered": "Geleverd",
            "held_back_by_haircut": "Ingehouden door de haircut",
            "when_you_settle_the_body_is_delivered": "Wanneer je afwikkelt, wordt het lichaam geleverd als PXA op het moment van uitvoering — een bedrag gelijk aan het door de oracle geïmpliceerde gewicht, vermenigvuldigd met de haircut. Daarom is ‘onderliggende waarde’ het verkeerde woord: een onderliggende waarde impliceert twee aparte activa, een ding en een derivaat erop. Maar de supra en de atlas zijn niet twee dingen. Ze zijn één lichaam gezien in twee registers — het lichaam is wat het is; de supra is wat de geest zegt dat dat lichaam moet projecteren. Het bewustzijn is niet iets wat het lichaam bezit. Het is het lichaam, ontwaakt.",
            "no_monetary_mechanism_removes_risk_a_stablecoin_concentrates": "Geen enkel monetair mechanisme neemt risico weg. Een coin met fiat-reserve concentreert het in de integriteit van die reserve en de solvabiliteit van een uitgever. De supra verplaatst dat risico naar de volatiliteit van de creatieve economie — de variantie van de Atlas — en naar de integriteit van de consensus — de deugdelijkheid van het witness-kompas — en beheert het vervolgens in de openbaarheid via overcollateralisatie en een niet-verdedigende haircut, in plaats van het te verhullen achter een verdedigd getal.",
