            "keep_them_in_a_safe_place_and": "Bewaar ze op een veilige plek en deel ze nooit. Ons team zal nooit om je privésleutels vragen.",
            "private_key_on_clipboard_warning": "Privésleutel gekopieerd. Het klembord is leesbaar voor andere apps en kan buiten dit apparaat synchroniseren — plak hem nu; hij wordt over 30 seconden overschreven.",
