            "permissions_use_your_key_to": "<b>{{title}}-machtigingen</b><br>Gebruik je {{title}} om:",
            "effective_in_strong_strong_day": "— van kracht over <strong>%n</strong> {{{_plurals.day}}}",
            "adding_a_password_provides_extra_security_especi": "Een wachtwoord toevoegen biedt extra veiligheid, vooral bij kortere seed phrases.",
            "you_are_about_to_request_a_change": "Je staat op het punt een wijziging van het herstelaccount aan te vragen voor <0>@{{username}}</0>.",
            "nominate_a_trusted_account_a_co_founder": "Wijs een vertrouwd account aan — een medeoprichter, een zusterwallet die je zelf beheert, of een contact dat je buiten het platform om kunt bereiken — om je te helpen weer toegang te krijgen als je owner-sleutel ooit verloren gaat of gecompromitteerd raakt. De herstelprocedure gebruikt je owner-sleutelgeschiedenis, dus het herstelaccount kan je account nooit in zijn eentje overnemen: het kan je alleen helpen het te herstellen. Wijzigingen worden van kracht na een wachtperiode van 30 dagen.",
            "strong_30_day_waiting_period_strong_changing": "<strong>Wachtperiode van 30 dagen.</strong> Het wijzigen van je herstelaccount is niet direct. Een nieuw verzoek wordt <strong>30 dagen na het uitzenden</strong> van kracht; tot die tijd blijft het huidige herstelaccount gelden. Opnieuw uitzenden tijdens de wachtperiode vervangt het lopende verzoek. Terugzetten naar de huidige waarde annuleert een lopende wijziging.",
            "pick_someone_you_trust_personally_a_co": "Kies iemand die je persoonlijk vertrouwt — een medeoprichter, een zusteraccount dat je zelf beheert, of een wallet waarvan je de eigenaar buiten het platform om kunt bereiken.",
            "generate_a_fresh_seed_phrase_to_derive": "Genereer een verse seed phrase om nieuwe sleutels voor je account af te leiden. Je seed phrase is de hoofdsleutel tot al je accountsleutels — bewaar hem veilig en deel hem nooit. De owner-sleutel wordt gebruikt om de sleutelupdate-transactie te ondertekenen wanneer je hieronder bevestigt.",
            "this_will_strong_cancel_any_pending_recovery": "Dit zal <strong>elke lopende wijziging van het herstelaccount annuleren</strong> door dezelfde waarde als je huidige herstelaccount opnieuw uit te zenden. Het lopende 30-dagenverzoek wordt vervangen; het huidige herstelaccount blijft ondertussen gewoon gelden.",
            "once_broadcast_the_chain_will_create_a": "Na het uitzenden maakt de chain een lopend verzoek aan dat over <strong>30 dagen</strong> van kracht wordt. Je huidige herstelaccount (<0>@{{currentRecovery}}</0>) blijft tot die tijd gelden. Je wordt om je <strong>owner-sleutel</strong> gevraagd.",
            "posting_description_1": "Deze sleutel is bedoeld voor sociale acties, zoals posten, reageren en stemmen. De sleutel heeft beperkte machtigingen en kan niet worden gebruikt voor geldgerelateerde acties.",
            "posting_description_2": "Gebruik deze sleutel om in te loggen op sociale netwerken op basis van Pixa, zoals Pixagram.com. Bewaar de sleutel veilig.",
            "active_description_1": "Deze sleutel heeft extra machtigingen voor gevoeligere geldgerelateerde acties, zoals het overboeken en wisselen van tokens.",
            "active_description_2": "Bij een wallet-gerelateerde actie kan je worden gevraagd je te verifiëren met je Active-sleutel. Voer je Active Key alleen in bij apps die je vertrouwt, want iedereen met toegang tot deze sleutel kan je tokens wegnemen.",
            "owner_description_1": "De Owner-sleutel is vereist om de andere sleutels te wijzigen. Deze sleutel heeft extra machtigingen om je account te herstellen of je andere sleutels te wijzigen. Het is de belangrijkste sleutel en moet veilig offline worden bewaard.",
            "memo_description_1": "De Memo-sleutel is een buitenbeentje. Het enige wat de Memo Key kan, is privéberichten versleutelen en ontsleutelen die via de blockchain worden verzonden.",
