            "pixasupra_is_a_type_of_token_which": "PixaSupra is een supracoin met oracle-referentie, gericht op <0>een wereldwijde meting van de koopkracht van echte goederen</0>. Het protocol verdedigt geen enkel getal, en de afwikkeling levert wat het onderpand kan dragen.",
            "the_price_feed_for_the_pixasupra_versus": "De prijsfeed van PixaSupra ten opzichte van Pixa ligt rond 1:57. De prijsfeed wordt gebruikt om de prikkels tussen de valuta’s te balanceren. PixaSupra en Pixa zoeken een evenwicht: er zouden <b>3,3x meer</b> liquide tokens moeten zijn dan tokens met oracle-referentie, zodat PixaSupra onder 30% van de Pixa-kapitalisatie blijft. Dat betekent dat we nu een marge van <b>3,7x</b> hebben om het aanbod te corrigeren: daalt de prijs van Pixa met zoveel, dan treedt de haircut-regel in werking.",
            "based_on_the_price_feed_1_57": "Op basis van de prijsfeed (1:57) en de PixaSupra (grofweg de Big Mac-index) ligt de gemiddelde prijs van één pixa-token rond de 10 dollarcent.",
            "similar_to_most_stablecoin_its_algorithms_requir": "Koerscorrectie is niet de hand van een operator aan een hendel: witnesses stemmen per consensus over de prijsfeed en de protocolparameters, en een eerlijke APR laat het systeem die feed volgen terwijl langetermijn-staking wordt beloond.",
            "the_blockchain_can_emit_various_ratio_of": "De blockchain kan PixaSupra en Pixa in wisselende verhoudingen uitgeven. Omdat PixaSupra tegen de koers met oracle-referentie in Pixa wordt geconverteerd, wordt de uitstaande PixaSupra afgezet tegen de Pixa-kapitalisatie.",
