        "community_principles": {
            "for_the_participants": "Voor de deelnemers",
            "creators_curators_stakeholders": "makers · curatoren · belanghebbenden",
            "for_the_community": "Voor de community",
            "marketers_developers_the_system": "marketeers · ontwikkelaars · het systeem",
            "the_active_hand_is_the_backbone": "De werkende hand is de ruggengraat.",
            "nothing_is_beautiful_but_the_artworks": "Niets is schoon behalve de werken",
            "create_first_for_your_own_joy": "Maak eerst om je eigen vreugde,",
            "strive_not_only_forwards_but_upwards": "Streef niet alleen voorwaarts, maar opwaarts,",
            "let_the_love_of_beautiful_artworks_be": "Laat de liefde voor schone werken een doel zijn,",
            "strive_ever_for_learning_and_improvement": "Streef altijd naar leren en beter worden,",
            "all_that_is_great_is_built_upon": "Al wat groot is, is op moeite gebouwd.",
            "discard_not_popularity": "Verwerp de populariteit niet,",
            "withhold_your_praise_as_freely_as_you": "Houd je lof even vrij in als je hem geeft.",
            "protect_the_young_and_harass_no_one": "Bescherm de jongsten en val niemand lastig.",
            "this_network_is_made_for_human_eyes": "Dit netwerk is gemaakt voor menselijke ogen en menselijke handen.",
            "reject_illusion_and_lies": "Verwerp illusie en leugen",
            "pixa_is_built_not_upon_sand_but": "Pixa is niet op zand gebouwd, maar op rots.",
            "the_dpf_builds_and_builds_only": "Het DPF bouwt, en bouwt alleen",
            "no_single_hand_owns_this_network": "Geen enkele hand bezit dit netwerk.",
            "the_code_is_open_and_the_door": "De code is open, en de deur staat open.",
            "hide_no_problem_and_promise_no_more": "Verberg geen enkel probleem en beloof niet meer dan kan worden waargemaakt.",
            "what_does_not_break_the_network_strengthens": "Wat het netwerk niet breekt, versterkt het.",
            "to_create_and_to_curate_is_worth": " Maken en cureren is meer waard dan zwijgend bezitten; wie komt opdagen is de levende substantie van Pixa, en voor hen is het eerst gebouwd.",
            "and_most_beautiful_of_all_are_the": " — en het schoonst van al zijn de handen die ze maken. Eer de maker in het werk.",
            "and_only_then_refine_your_work_to": " en verfijn je werk pas daarna zodat het stijgt. Het plezier in het vak komt eerst; de ambitie voor het werk komt daarna.",
            "for_greatness_lies_in_the_highest_to": " want de grootheid ligt in het hoogste. Vaak posten is goed; goed posten is groter.",
            "but_let_your_highest_goal_be_their": " maar laat je hoogste doel hun betekenis zijn — want wat betekenis draagt, is wat blijft.",
            "for_conquest_is_never_accomplished_no_milestone": " want de verovering is nooit voltooid. Geen mijlpaal is een top; het werk is nooit af.",
            "lift_the_smallest_accounts_as_you_climb": " Til de kleinste accounts op terwijl je klimt, want het kleine visje van vandaag is de meester van morgen.",
            "but_treat_it_sometimes_as_an_impostor": " maar behandel haar soms als een bedriegster — en wees altijd rechtvaardig. Wat de menigte liefheeft, is niet altijd het beste; blijf je eigen rechter.",
            "to_dislike_is_your_right_and_to": " Iets niet mooi vinden is je recht, en oordelen is niet censureren; downvote of loop voorbij aan elk werk dat je niet raakt.",
            "a_community_is_known_by_how_it": " Een community herken je aan hoe ze de kwetsbaren beschermt; keer je kracht naar het scheppen, nooit tegen een ander.",
            "let_every_tool_serve_the_creator_and": " Laat elk gereedschap de maker dienen en nooit zijn plaats innemen.",
            "in_your_work_and_in_your_dealings": " in je werk en in je omgang, want eerlijkheid is de rots waarop alle kracht is gebouwd.",
            "contribute_to_it_not_for_today_or": " Draag eraan bij, niet voor vandaag en niet voor gisteren, maar voor altijd.",
            "it_funds_development_and_the_protocol_the": " — het financiert de ontwikkeling en het protocol. De promotie van Pixa behoort aan haar mensen, nooit aan haar schatkist.",
            "the_foundation_stewards_it_does_not_rule": " De Foundation beheert; ze heerst niet. Wat hier gebouwd wordt, behoort aan allen die het bouwen.",
            "should_governance_ever_fail_the_community_may": " Mocht de governance ooit falen, dan mag de community het werk elders voortzetten, in zijn geheel.",
            "what_is_true_is_said_plainly_even": " Wat waar is, wordt eenvoudig gezegd, ook wanneer een comfortabele fictie makkelijker zou zijn.",
            "we_endure_by_bending_to_the_storm": " Wij houden stand door te buigen voor de storm, niet door te doen alsof er geen komt.",
            "uniquely_we_are_free_together_we_are_stronger": "Als enkeling zijn we vrij; samen zijn we sterker.",
            "these_principles_are_the_foundation_of_pixa": "Deze principes vormen het fundament van Pixa en van de community die we erop bouwen — oprecht, eerlijk, duurzaam en verenigd. Het protocol verbiedt alleen wat het moet verbieden; al het goede voorbij die grens is het karakter dat we kiezen. Dit is dat karakter: de geest waarin we creëren, de manier waarop we met elkaar omgaan en de maatstaf waaraan we onszelf houden. Ze binden niemand met dwang, en toch binden ze ons allemaal.",
            "free_in_our_hands_united_in_our_purpose": "Vrij in onze handen, verenigd in ons doel — <0>we bouwen voor altijd.</0>"
        },
