            "no_naimap_set_nai_asset_objects_are_skipped": "Geen naiMap ingesteld — alle {amount,precision,nai}-assetobjecten (niet-condenser-API’s) worden overgeslagen. Gebruik condenser_api/get_account_history (legacy strings) of voeg een naiMap toe.",
