            "this_license_delegates_and_allocates_copyright": "Deze licentie draagt auteursrechtelijke bevoegdheden, die standaard zeer strikt zijn, van de Maker over aan de NFT-eigenaar(s) en Bezoeker(s) en verdeelt ze onder hen. De Maker behoudt het volledige intellectuele eigendom en verleent specifieke gebruiksrechten op basis van de eigen voorkeuren.",
