            "legal_agreement": "Juridische overeenkomst",
            "this_nft_license_agreement_the_agreement": "Deze NFT-licentieovereenkomst (de ‘Overeenkomst’) bepaalt de aanpasbare voorwaarden waaronder de schepper (hierna de ‘Maker’ genoemd) bepaalde rechten verleent aan de koper (de ‘Houder’) van non-fungible tokens (NFT’s) die zijn gekoppeld aan een specifieke collectie digitale kunstwerken (de ‘Collectie’). Het doel van deze Overeenkomst is een flexibel, transparant en eerlijk licentiekader te bieden dat zich kan aanpassen aan verschillende gebruikssituaties, bedrijfsmodellen en artistieke bedoelingen, en tegelijk te waarborgen dat de morele rechten van de Maker intact en volledig behouden blijven. Deze structuur is in het bijzonder bedoeld voor NFT-makers die houders van hun digitale activa op maat gemaakte gebruiksrechten willen bieden, waardoor afhankelijk van de door de Maker gekozen voorkeuren een reeks interacties met en exploitaties van het kunstwerk mogelijk wordt.",
            "ownership_and_moral_rights": "Eigendom en morele rechten",
            "the_author_is_and_shall_remain_the_sole": "De Maker is en blijft de enige en exclusieve eigenaar van alle intellectuele-eigendomsrechten op de onderliggende kunstwerken en alle bijbehorende inhoud die aan de NFT’s is gekoppeld. De Maker behoudt alle morele rechten, waaronder het recht om als schepper te worden vermeld en het recht zich te verzetten tegen elke misvorming, verminking of andere wijziging van het werk die zijn of haar eer of reputatie zou schaden. Deze morele rechten zijn niet overdraagbaar en eeuwigdurend, en moeten door alle Houders en derden worden gerespecteerd. Deze Overeenkomst mag niet worden uitgelegd als een afstand of beperking van die rechten.",
            "license_options_for_the_holder": "Licentieopties voor de Houder",
            "the_holder_of_an_nft_is_granted_a_non": "Aan de Houder van een NFT wordt een niet-exclusieve, wereldwijde, royaltyvrije licentie verleend om het aan de NFT gekoppelde digitale kunstwerk te gebruiken, maar alleen voor zover de Maker dit hieronder uitdrukkelijk toestaat. De licentie is strikt gekoppeld aan de specifieke NFT die in bezit is en gaat bij doorverkoop automatisch over. Het doel van dit artikel is de Maker in staat te stellen de omvang van de aan elke Houder verleende rechten te kiezen, en zo beide partijen juridische duidelijkheid en creatieve flexibiliteit te bieden. Voor elk vermeld recht kan de Maker aangeven of de Houder het mag uitoefenen.",
