            "the_author_shall_receive_a_royalty_of": "De Maker ontvangt een royalty van **{{royaltyPercentage}}%** op alle doorverkopen of overdrachten van de NFT’s, ongeacht de marktplaats of de wijze van transactie. Deze royalty wordt, waar ondersteund, automatisch afgedwongen via smart-contractfunctionaliteit. Indien de transactie buiten een geautomatiseerd systeem plaatsvindt, is de verkoper ervoor verantwoordelijk dat de Maker de verschuldigde royalty ontvangt en dat de voornoemde rechten worden nageleefd.",
